class URLHandler:
    SCHEME_SEPARATOR = "://"
    PATH_SEPARATOR = "/"
    QUERY_SEPARATOR = "?"
    FRAGMENT_SEPARATOR = "#"
    PARAM_SEPARATOR = "&"
    KEY_VALUE_SEPARATOR = "="
    SCHEME_SEPARATOR_LENGTH = 3

    def __init__(self, url):
        self._url = url

    @property
    def url(self):
        return self._url

    @url.setter
    def url(self, value):
        self._url = value

    def _find_scheme_end(self):
        return self._url.find(self.SCHEME_SEPARATOR)

    def get_scheme(self):
        scheme_end = self._find_scheme_end()
        if scheme_end != -1:
            return self._url[:scheme_end]
        return None

    def _get_url_without_scheme(self):
        scheme_end = self._find_scheme_end()
        if scheme_end != -1:
            return self._url[scheme_end + self.SCHEME_SEPARATOR_LENGTH:]
        return None

    def get_host(self):
        url_without_scheme = self._get_url_without_scheme()
        if url_without_scheme is None:
            return None
        host_end = url_without_scheme.find(self.PATH_SEPARATOR)
        if host_end != -1:
            return url_without_scheme[:host_end]
        return url_without_scheme

    def get_path(self):
        url_without_scheme = self._get_url_without_scheme()
        if url_without_scheme is None:
            return None
        host_end = url_without_scheme.find(self.PATH_SEPARATOR)
        if host_end != -1:
            return url_without_scheme[host_end:]
        return None

    def get_query_params(self):
        query_start = self._url.find(self.QUERY_SEPARATOR)
        if query_start == -1:
            return None
        fragment_start = self._url.find(self.FRAGMENT_SEPARATOR)
        query_string = self._extract_query_string(query_start, fragment_start)
        if not query_string:
            return {}
        return self._parse_query_string(query_string)

    def _extract_query_string(self, query_start, fragment_start):
        if fragment_start != -1:
            return self._url[query_start + 1:fragment_start]
        return self._url[query_start + 1:]

    def _parse_query_string(self, query_string):
        params = {}
        param_pairs = query_string.split(self.PARAM_SEPARATOR)
        for pair in param_pairs:
            self._parse_param_pair(pair, params)
        return params

    def _parse_param_pair(self, pair, params):
        key_value = pair.split(self.KEY_VALUE_SEPARATOR)
        if len(key_value) == 2:
            key, value = key_value
            params[key] = value

    def get_fragment(self):
        fragment_start = self._url.find(self.FRAGMENT_SEPARATOR)
        if fragment_start != -1:
            return self._url[fragment_start + 1:]
        return None
